  T = any,
  S extends StrictRJSFSchema = RJSFSchema,
  F extends FormContextType = any,
>(validator: ValidatorType<T, S, F>, schema: S, rootSchema: S, formData: any): any | undefined {
  // An undefined `formData` is always processed to `undefined`.
  if (formData === undefined) {
    return undefined;
  }

  // Scalars (non-object, non-array values) are returned unchanged.
  if (!isObject(formData) && !Array.isArray(formData)) {
    return formData;
  }

  // Without a schema there is nothing to process against, so return the data unchanged.
  if (!schema) {
    return formData;
